 private async reconcileWorkspaces(){if(!this.app)return;const rows=await this.workspaceRows(),records=(await this.app.sync.list(this.actor())).records;for(const workspace of rows){if(workspace.mode!=='continuity'||!workspace.source_device_id)continue;const peer=await this.currentPeer(workspace.source_device_id),id=deviceIdOf(peerKey(peer.publicKey)),selection=JSON.parse(workspace.selection_json);let applied=0;for(const selected of selection){const record=records.filter(r=>r.peerId===id&&r.category===selected.category&&r.logicalId===selected.logicalId&&r.direction==='in'&&r.state==='applied').sort((a,b)=>b.revision-a.revision)[0];if(!record)continue;const mapping=await this.app.sync.continueWorkspaceSelection(this.actor(),record.id);await q.run('INSERT INTO dpro_workspace_resources(user_id,account_id,workspace_id,category,local_id,logical_id) VALUES(?,?,?,?,?,?) ON CONFLICT(user_id,account_id,workspace_id,category,local_id) DO UPDATE SET logical_id=excluded.logical_id',this.ownerId!,this.scope(),workspace.workspace_id,selected.category,mapping.localId,selected.logicalId);applied++;}await q.run('UPDATE dpro_workspaces SET state=? WHERE user_id=? AND account_id=? AND workspace_id=?',applied===selection.length?'ready':'waiting_local_review',this.ownerId!,this.scope(),workspace.workspace_id);}}
