 async denyRequest(actor:Actor,input:any){await this.owner(actor);exact(input,['deviceId','confirmed']);if(input.confirmed!==true||!validId(input.deviceId))throw Error('account_input_invalid');this.lastView=projectAccountView(await this.client!.request('device.deny',{deviceId:input.deviceId,confirmed:true}));this.pairSeen.delete(input.deviceId);return {denied:true};}
